import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"科技空岛常用命令","description":"快速查找回岛、面板、任务、升级、权限、余额和矿物额度命令。","frontmatter":{"title":"科技空岛常用命令","description":"快速查找回岛、面板、任务、升级、权限、余额和矿物额度命令。"},"headers":[],"relativePath":"skyblock/commands.md","filePath":"skyblock/commands.md"}`),a={name:`skyblock/commands.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="科技空岛常用命令" tabindex="-1">科技空岛常用命令 <a class="header-anchor" href="#科技空岛常用命令" aria-label="Permalink to “科技空岛常用命令”">​</a></h1><p>想回家，或者只是忘记任务菜单怎么开？先看这张表。以下用于科技空岛，具体权限、参数、延迟和冷却以当前服内帮助为准。</p><h2 id="岛屿与资源" tabindex="-1">岛屿与资源 <a class="header-anchor" href="#岛屿与资源" aria-label="Permalink to “岛屿与资源”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用来做什么</th></tr></thead><tbody><tr><td><code>/is</code></td><td>岛屿主入口，按当前状态与菜单创建或管理岛屿</td></tr><tr><td><code>/is panel</code></td><td>打开岛屿管理面板</td></tr><tr><td><code>/is tp</code></td><td>返回岛屿</td></tr><tr><td><code>/is missions</code></td><td>打开岛屿任务</td></tr><tr><td><code>/is upgrade</code></td><td>打开岛屿升级，注意是 <code>upgrade</code></td></tr><tr><td><code>/is permissions</code></td><td>管理岛屿权限</td></tr><tr><td><code>/is biome</code></td><td>打开生物群系设置</td></tr><tr><td><code>/is bank</code></td><td>打开岛屿银行</td></tr><tr><td><code>/is top</code></td><td>查看岛屿榜单</td></tr><tr><td><code>/bq status</code></td><td>查询当前位置所属范围的矿物生成额度</td></tr></tbody></table><h2 id="出生点与余额" tabindex="-1">出生点与余额 <a class="header-anchor" href="#出生点与余额" aria-label="Permalink to “出生点与余额”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用来做什么</th></tr></thead><tbody><tr><td><code>/spawn</code></td><td>返回公共出生点，存在短延迟与冷却</td></tr><tr><td><code>/bal</code> 或 <code>/balance</code></td><td>查询游戏内余额</td></tr><tr><td><code>/pay</code></td><td>游戏内转账；先查看服内帮助确认参数与权限</td></tr></tbody></table><p>转账前请核对目标玩家和金额。这里的余额说明不代表与增强生存共享经济，也不代表存在商店或拍卖行。</p><h2 id="常用命令-点一下复制" tabindex="-1">常用命令，点一下复制 <a class="header-anchor" href="#常用命令-点一下复制" aria-label="Permalink to “常用命令，点一下复制”">​</a></h2><p>下列代码块右上角提供复制按钮，复制后贴入游戏聊天栏即可。</p><p>回岛：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/is tp</span></span></code></pre></div><p>管理面板：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/is panel</span></span></code></pre></div><p>查看任务：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/is missions</span></span></code></pre></div><p>查看额度：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/bq status</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">还没有漂流鱼竿？</p><p>初始鱼竿的获取方式尚待确认，请按服内引导或询问管理员。管理员发放命令不是普通玩家的领取方式。</p></div><p><a href="./getting-started.html">新手入门</a> · <a href="./resources.html">任务与资源额度</a> · <a href="./fishing-rewards.html">漂流钓鱼奖池</a></p>`,19)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};